import 'dart:async';
import 'dart:math';

import 'package:flutter/material.dart';

import '../main.dart';
import 'session.dart';

/// Parking-jam + colour passengers (Bus Jam style).
///
/// Vehicles point in a direction; tapping one drives it out if the road ahead
/// is clear. It then waits at the stop and boards passengers of its colour.
/// Vehicles are generated by insertion with a clear road (so a valid exit
/// order exists) and the passenger queue follows that order.
const _colors = [
  Color(0xFFE53935),
  Color(0xFF1E88E5),
  Color(0xFF43A047),
  Color(0xFFFDD835),
  Color(0xFF8E24AA),
  Color(0xFFFB8C00),
];

class BusCar {
  BusCar(this.r, this.c, this.len, this.dr, this.dc, this.color);
  final int r, c, len, dr, dc, color;
  int seats = 0;
  int get capacity => len + 1;

  /// Cells occupied, front first.
  List<(int, int)> get cells => [
    for (var k = 0; k < len; k++) (r - dr * k, c - dc * k),
  ];
}

class BusLevel {
  BusLevel(this.size, this.cars, this.queue);
  final int size;
  final List<BusCar> cars;
  final List<int> queue;
}

bool busRoadClear(int size, List<BusCar> cars, BusCar car) {
  final taken = {
    for (final o in cars)
      if (o != car) ...o.cells,
  };
  var r = car.r + car.dr, c = car.c + car.dc;
  while (r >= 0 && r < size && c >= 0 && c < size) {
    if (taken.contains((r, c))) return false;
    r += car.dr;
    c += car.dc;
  }
  return true;
}

BusLevel busLevel(int level, int seed) {
  final rnd = Random(seed);
  final size = (6 + level ~/ 10).clamp(6, 8);
  final target = (5 + level ~/ 2).clamp(5, 18);
  final nColors = (3 + level ~/ 8).clamp(3, _colors.length);
  final cars = <BusCar>[];
  const dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)];
  var attempts = 0;
  while (cars.length < target && attempts < 4000) {
    attempts++;
    final (dr, dc) = dirs[rnd.nextInt(4)];
    final len = rnd.nextDouble() < 0.7 ? 2 : 3;
    final car = BusCar(
      rnd.nextInt(size),
      rnd.nextInt(size),
      len,
      dr,
      dc,
      rnd.nextInt(nColors),
    );
    final occupied = {for (final o in cars) ...o.cells};
    final ok = car.cells.every(
      (p) =>
          p.$1 >= 0 &&
          p.$1 < size &&
          p.$2 >= 0 &&
          p.$2 < size &&
          !occupied.contains(p),
    );
    if (ok && busRoadClear(size, [...cars, car], car)) cars.add(car);
  }
  // Exit order = reverse insertion. Queue follows it; from level 6 on, pairs
  // of consecutive groups are interleaved so two vehicles must wait at once.
  final order = cars.reversed.toList();
  final queue = <int>[];
  for (var i = 0; i < order.length; i += 2) {
    final a = List.filled(order[i].capacity, order[i].color);
    final b = i + 1 < order.length
        ? List.filled(order[i + 1].capacity, order[i + 1].color)
        : <int>[];
    if (level >= 6 && b.isNotEmpty) {
      // Random merge keeps each group's internal order.
      var ia = 0, ib = 0;
      while (ia < a.length || ib < b.length) {
        final takeA = ib >= b.length || (ia < a.length && rnd.nextBool());
        queue.add(takeA ? a[ia++] : b[ib++]);
      }
    } else {
      queue
        ..addAll(a)
        ..addAll(b);
    }
  }
  return BusLevel(size, cars, queue);
}

class BusGame extends StatefulWidget {
  const BusGame({super.key, required this.session});
  final GameSession session;

  @override
  State<BusGame> createState() => _BusGameState();
}

class _BusGameState extends State<BusGame> {
  late final BusLevel _lv = busLevel(widget.session.level, widget.session.seed);
  final List<BusCar?> _stop = List.filled(4, null);
  Timer? _timer;
  bool _over = false;
  BusCar? _hinted;
  BusCar? _blocked;

  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(milliseconds: 160), (_) => _board());
    widget.session.hint.addListener(_hint);
  }

  @override
  void dispose() {
    _timer?.cancel();
    widget.session.hint.removeListener(_hint);
    super.dispose();
  }

  void _hint() {
    final front = _lv.queue.isEmpty ? null : _lv.queue.first;
    final free = _lv.cars.where((c) => busRoadClear(_lv.size, _lv.cars, c));
    final pick =
        free.where((c) => c.color == front).firstOrNull ?? free.firstOrNull;
    if (pick != null) setState(() => _hinted = pick);
  }

  void _tap(BusCar car) {
    if (_over) return;
    if (!busRoadClear(_lv.size, _lv.cars, car)) {
      setState(() => _blocked = car);
      Future.delayed(const Duration(milliseconds: 300), () {
        if (mounted) setState(() => _blocked = null);
      });
      return;
    }
    final slot = _stop.indexOf(null);
    if (slot < 0) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(
          SnackBar(
            content: Text(GameApp.of(context).t.t('noSlot')),
            duration: const Duration(milliseconds: 900),
          ),
        );
      return;
    }
    setState(() {
      _lv.cars.remove(car);
      _stop[slot] = car;
      if (_hinted == car) _hinted = null;
    });
  }

  /// One passenger boards per tick; full vehicles leave the stop.
  void _board() {
    if (_over) return;
    if (_lv.queue.isNotEmpty) {
      final color = _lv.queue.first;
      final idx = _stop.indexWhere((c) => c != null && c.color == color);
      if (idx >= 0) {
        setState(() {
          final car = _stop[idx]!;
          car.seats++;
          _lv.queue.removeAt(0);
          if (car.seats >= car.capacity) _stop[idx] = null;
        });
        return;
      }
    }
    if (_lv.queue.isEmpty &&
        _lv.cars.isEmpty &&
        _stop.every((c) => c == null)) {
      _over = true;
      widget.session.onWin();
      return;
    }
    // Stuck: stop full and nobody at the stop matches the next passenger.
    if (!_stop.contains(null) && _lv.queue.isNotEmpty) {
      _over = true;
      widget.session.onFail();
    }
  }

  @override
  Widget build(BuildContext context) {
    final n = _lv.size;
    return Column(
      children: [
        // Passenger queue (front on the left).
        SizedBox(
          height: 44,
          child: ListView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            children: [
              for (final (i, p) in _lv.queue.take(18).indexed)
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 1),
                  child: Icon(
                    Icons.person,
                    color: _colors[p],
                    size: i == 0 ? 40 : 30,
                  ),
                ),
            ],
          ),
        ),
        // The stop.
        Padding(
          padding: const EdgeInsets.symmetric(vertical: 8),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              for (final car in _stop)
                Container(
                  margin: const EdgeInsets.all(4),
                  width: 70,
                  height: 48,
                  decoration: BoxDecoration(
                    color: car == null
                        ? Colors.black.withValues(alpha: 0.06)
                        : _colors[car.color],
                    borderRadius: BorderRadius.circular(12),
                  ),
                  alignment: Alignment.center,
                  child: car == null
                      ? const Icon(Icons.local_parking, color: Colors.black26)
                      : Text(
                          '${car.seats}/${car.capacity}',
                          style: const TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.w900,
                            fontSize: 18,
                          ),
                        ),
                ),
            ],
          ),
        ),
        Expanded(
          child: Center(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: AspectRatio(
                aspectRatio: 1,
                child: Container(
                  decoration: BoxDecoration(
                    color: const Color(0xFF455A64),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: LayoutBuilder(
                    builder: (context, box) {
                      final cell = box.maxWidth / n;
                      return Stack(
                        children: [for (final car in _lv.cars) _car(car, cell)],
                      );
                    },
                  ),
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }

  Widget _car(BusCar car, double cell) {
    final cells = car.cells;
    final rows = cells.map((e) => e.$1);
    final cols = cells.map((e) => e.$2);
    final top = rows.reduce(min), left = cols.reduce(min);
    final h = rows.reduce(max) - top + 1, w = cols.reduce(max) - left + 1;
    final icon = switch ((car.dr, car.dc)) {
      (-1, 0) => Icons.keyboard_arrow_up,
      (1, 0) => Icons.keyboard_arrow_down,
      (0, -1) => Icons.keyboard_arrow_left,
      _ => Icons.keyboard_arrow_right,
    };
    final highlight = _hinted == car;
    return Positioned(
      left: left * cell,
      top: top * cell,
      width: w * cell,
      height: h * cell,
      child: GestureDetector(
        onTap: () => _tap(car),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 150),
          margin: EdgeInsets.all(cell * 0.08),
          decoration: BoxDecoration(
            color: _blocked == car ? Colors.red.shade200 : _colors[car.color],
            borderRadius: BorderRadius.circular(cell * 0.25),
            border: Border.all(
              color: highlight ? Colors.amber : Colors.white70,
              width: highlight ? 4 : 2,
            ),
          ),
          child: Icon(icon, color: Colors.white, size: cell * 0.8),
        ),
      ),
    );
  }
}
